o:[{hi:'30 सेकंड',en:'30 seconds'},{hi:'45 सेकंड',en:'45 seconds'},{hi:'60 सेकंड',en:'60 seconds'},{hi:'25 सेकंड',en:'25 seconds'}],d:3,a:1,src:{hi:'RRB Group D 2022',en:'RRB Group D 2022'},
