o:[{hi:'1:1',en:'1:1'},{hi:'2:1',en:'2:1'},{hi:'1:2',en:'1:2'},{hi:'3:2',en:'3:2'}],d:2,a:0,src:{hi:'RRB NTPC 2021',en:'RRB NTPC 2021'},
