o:[{hi:'1:1',en:'1:1'},{hi:'2:3',en:'2:3'},{hi:'3:2',en:'3:2'},{hi:'2:1',en:'2:1'}],d:1,a:0,src:{hi:'RRB ALP 2019',en:'RRB ALP 2019'},
